"""JWT migration regressions using only public, synthetic authentication data."""

from datetime import datetime, timezone
import importlib.util
import unittest

from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa

from core.jwt_codec import JWTError, jwt


KEY = "synthetic-only-compatibility-key-32bytes-minimum"
# Generated by the retired python-jose3.5.0, not by the implementation under test.
# This is a public fixture, NOT a real user/session/token or application secret.
LEGACY_ACCESS = (
    "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9."
    "eyJzdWIiOiI0MiIsInR5cGUiOiJhY2Nlc3MiLCJzaWQiOiJzeW50aGV0aWMtc2Vzc2lvbiIs"
    "InNydiI6ImZvcmVpZ24iLCJleHAiOjIxNDU5MTY4MDB9."
    "nb85KHHKuiD38RC8ei5WZzPP2p5vjVUDzaqEFH_41CI"
)


class JwtCodecSecurityTests(unittest.TestCase):
    def decode(self, token, *, key=KEY):
        return jwt.decode(token, key, algorithms=["HS256"])

    def test_existing_legacy_signed_token_remains_valid(self):
        self.assertEqual(self.decode(LEGACY_ACCESS), {
            "sub": "42", "type": "access", "sid": "synthetic-session",
            "srv": "foreign", "exp": 2145916800,
        })

    def test_wire_format_remains_compatible_for_access_and_refresh_claims(self):
        claims = self.decode(LEGACY_ACCESS)
        self.assertEqual(jwt.encode(claims, KEY, algorithm="HS256"), LEGACY_ACCESS)
        for kind in ("access", "refresh", "registration"):
            with self.subTest(kind=kind):
                payload = {**claims, "type": kind}
                self.assertEqual(self.decode(jwt.encode(payload, KEY, algorithm="HS256")), payload)

    def test_wrong_key_wrong_algorithm_unsigned_and_tampered_tokens_are_rejected(self):
        payload = self.decode(LEGACY_ACCESS)
        tokens = [
            jwt.encode(payload, KEY + "-wrong", algorithm="HS256"),
            jwt.encode(payload, KEY * 2, algorithm="HS384"),
            jwt.encode(payload, None, algorithm="none"),
            LEGACY_ACCESS.replace("eyJzdWIi", "eyJzdWJi", 1),
        ]
        for index, token in enumerate(tokens):
            with self.subTest(case=index), self.assertRaises(JWTError):
                self.decode(token)

    def test_expiry_not_before_and_issued_at_checks_remain_enabled(self):
        now = int(datetime.now(timezone.utc).timestamp())
        for change in ({"exp": now - 60}, {"nbf": now + 3600}, {"iat": now + 3600}):
            with self.subTest(claim=next(iter(change))), self.assertRaises(JWTError):
                self.decode(jwt.encode({"sub": "42", **change}, KEY, algorithm="HS256"))

    def test_subject_identifier_and_audience_validation_remain_enabled(self):
        for change in ({"sub": 42}, {"jti": 42}, {"aud": "unrequested-audience"}):
            with self.subTest(claim=next(iter(change))), self.assertRaises(JWTError):
                self.decode(jwt.encode(change, KEY, algorithm="HS256"))

    def test_mutated_asymmetric_public_keys_cannot_be_used_as_hmac_keys(self):
        public = rsa.generate_private_key(public_exponent=65537, key_size=2048).public_key()
        pem = public.public_bytes(serialization.Encoding.PEM, serialization.PublicFormat.SubjectPublicKeyInfo)
        for index, key in enumerate((pem, b"\n" + pem, pem.replace(b"\n", b"\r\n"))):
            with self.subTest(case=index), self.assertRaises(JWTError):
                jwt.encode({"sub": "42"}, key, algorithm="HS256")

    def test_retired_unpatched_libraries_are_not_installed(self):
        self.assertIsNone(importlib.util.find_spec("jose"))
        self.assertIsNone(importlib.util.find_spec("ecdsa"))
